package com.swiftpay.analytics.kafka; import com.fasterxml.jackson.databind.ObjectMapper; import com.swiftpay.analytics.entity.PaymentAnalytics; import com.swiftpay.analytics.repository.AnalyticsRepository; import java.math.BigDecimal; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class AnalyticsListener {private final AnalyticsRepository repo;private final ObjectMapper mapper;public AnalyticsListener(AnalyticsRepository r,ObjectMapper m){repo=r;mapper=m;} @KafkaListener(topics="swiftpay.payment.completed",groupId="analytics-worker") public void onMessage(String value)throws Exception{Event e=mapper.readValue(value,Event.class);try{repo.saveAndFlush(new PaymentAnalytics(e.transactionId(),e.amount()));}catch(DataIntegrityViolationException ignored){}} record Event(String eventId,String originalEventId,String transactionId,String senderId,String receiverId,BigDecimal amount,String currency,String status,String reason,java.time.Instant timestamp){}
}